#include <map>
#include <string>
#include <iostream>

int main() {
    std::map<std::string, float> coll;

    // Insertion 1: Successful
    auto result1 = coll.insert(std::make_pair("otto", 22.3f));
    if (result1.second) {
        std::cout << "Inserted: " << result1.first->second << "\n";
    }

    // Insertion 2: Key collision
    auto result2 = coll.insert(std::make_pair("otto", 99.9f));
    if (!result2.second) {
        std::cout << "Failed. Existing value: " 
                  << result2.first->second << "\n";
    }
}
